-- ===================== Joshua — EASY tier (10 items) =====================

with w as (select id from public.world where book_slug = 'joshua')
insert into public.challenge (world_id, type, prompt, verse_ref, verse_text, translation, difficulty_rank, difficulty_tier, answer_key, is_boss_item, sort_order)
values
  ((select id from w), 'multiple_choice', 'What did Joshua tell the two spies to do?', 'Joshua 2:1', 'Joshua the son of Nun secretly sent two men out of Shittim as spies, saying, ''Go, view the land, including Jericho.''...', 'WEB', 1, 'easy',
   '{"type": "multiple_choice", "options": ["View the land, including Jericho", "Attack the king of Jericho", "Bring back gold from Jericho", "Meet with Rahab in secret"], "correct_index": 0}', false, 1),
  ((select id from w), 'multiple_choice', 'What did Rahab tie in her window as a sign?', 'Joshua 2:21', 'She said, ''Let it be as you have said.'' She sent them away, and they departed. Then she tied the scarlet line in the window.', 'WEB', 1, 'easy',
   '{"type": "multiple_choice", "options": ["a scarlet line", "a white flag", "a blue cord", "a bundle of straw"], "correct_index": 0}', false, 2),
  ((select id from w), 'multiple_choice', 'How did Israel cross the Jordan River?', 'Joshua 3:16-17', '...the waters which came down from above stood, and rose up in one heap a great way off, at Adam, the city that is beside Zarethan... Then the people passed over near Jericho. The priests who bore the ark of Yahweh''s covenant stood firm on dry ground in the middle of the Jordan; and all Israel crossed over on dry ground, until all the nation had passed completely over the Jordan.', 'WEB', 1, 'easy',
   '{"type": "multiple_choice", "options": ["On dry ground, because the waters stood in a heap", "By boat, one tribe at a time", "By swimming across", "They did not cross the Jordan"], "correct_index": 0}', false, 3),
  ((select id from w), 'multiple_choice', 'What were the stones set up at the Jordan to help future generations remember?', 'Joshua 4:6-7', '...that this may be a sign among you, that when your children ask in the future, saying, What do you mean by these stones? then you shall tell them, Because the waters of the Jordan were cut off before the ark of Yahweh''s covenant. When it crossed over the Jordan, the waters of the Jordan were cut off. These stones shall be for a memorial to the children of Israel forever.', 'WEB', 1, 'easy',
   '{"type": "multiple_choice", "options": ["That the waters of the Jordan were cut off before the ark of Yahweh''s covenant", "A battle Israel won at Jericho", "The Ten Commandments", "Moses'' death"], "correct_index": 0}', false, 4),
  ((select id from w), 'multiple_choice', 'What happened when the people shouted and the priests blew the trumpets at Jericho?', 'Joshua 6:20', 'So the people shouted and the priests blew the trumpets. When the people heard the sound of the trumpet, the people shouted with a great shout, and the wall fell down flat, so that the people went up into the city, every man straight in front of him, and they took the city.', 'WEB', 1, 'easy',
   '{"type": "multiple_choice", "options": ["The wall fell down flat", "The city gates opened peacefully", "Nothing happened", "The people were struck silent"], "correct_index": 0}', false, 5),
  ((select id from w), 'multiple_choice', 'According to Joshua 6:25, whom did Joshua save alive?', 'Joshua 6:25', 'But Rahab the prostitute, her father''s household, and all that she had, Joshua saved alive. She lives in the middle of Israel to this day, because she hid the messengers whom Joshua sent to spy out Jericho.', 'WEB', 1, 'easy',
   '{"type": "multiple_choice", "options": ["Rahab and her father''s household", "The king of Jericho", "All the city''s soldiers", "The two spies'' own families"], "correct_index": 0}', false, 6),
  ((select id from w), 'multiple_choice', 'How old was Caleb when he asked Joshua for the hill country?', 'Joshua 14:10-12', '...Now, behold, I am eighty-five years old, today. As yet I am as strong today as I was in the day that Moses sent me... Now therefore give me this hill country, of which Yahweh spoke in that day...', 'WEB', 1, 'easy',
   '{"type": "multiple_choice", "options": ["eighty-five years old", "forty years old", "one hundred years old", "twenty years old"], "correct_index": 0}', false, 7),
  ((select id from w), 'sequence', 'Order these events of the entry into Canaan in the order they happen in the text.', 'Joshua 2:1; 3:16-17; 4:6-7; 6:20', 'Joshua the son of Nun secretly sent two men out of Shittim as spies, saying, ''Go, view the land, including Jericho.''...; ...the waters which came down from above stood, and rose up in one heap a great way off, at Adam, the city that is beside Zarethan... Then the people passed over near Jericho. The priests who bore the ark of Yahweh''s covenant stood firm on dry ground in the middle of the Jordan; and all Israel crossed over on dry ground, until all the nation had passed completely over the Jordan.; ...that this may be a sign among you, that when your children ask in the future, saying, What do you mean by these stones? then you shall tell them, Because the waters of the Jordan were cut off before the ark of Yahweh''s covenant. When it crossed over the Jordan, the waters of the Jordan were cut off. These stones shall be for a memorial to the children of Israel forever.; So the people shouted and the priests blew the trumpets. When the people heard the sound of the trumpet, the people shouted with a great shout, and the wall fell down flat, so that the people went up into the city, every man straight in front of him, and they took the city.', 'WEB', 1, 'easy',
   '{"type": "sequence", "items": ["Joshua sends two spies to Jericho", "Israel crosses the Jordan on dry ground", "stones are set up as a memorial", "Israel marches around Jericho and the wall falls"], "correct_order": [0, 1, 2, 3]}', true, 8),
  ((select id from w), 'recall', 'Fill in the missing word: what did Yahweh give to Israel, according to Joshua 21:43-45?', 'Joshua 21:43-45', 'So Yahweh gave to Israel all the land which he swore to give to their fathers. They possessed it, and lived in it. Yahweh gave them rest all around, according to all that he swore to their fathers. Not a man of all their enemies stood before them. Yahweh delivered all their enemies into their hand. Nothing failed of any good thing which Yahweh had spoken to the house of Israel. All came to pass.', 'WEB', 1, 'easy',
   '{"type": "recall", "template": "So Yahweh gave to Israel all the ___ which he swore to give to their fathers.", "answer": "land"}', true, 9),
  ((select id from w), 'recall', 'Fill in the missing place name from Joshua''s campaign summary.', 'Joshua 10:41', 'Joshua struck them from Kadesh Barnea even to Gaza, and all the country of Goshen, even to Gibeon. Joshua took all these kings and their land at one time because Yahweh, the God of Israel, fought for Israel.', 'WEB', 1, 'easy',
   '{"type": "recall", "template": "Joshua struck them from Kadesh Barnea even to Gaza, and all the country of Goshen, even to ___.", "answer": "Gibeon"}', true, 10)
;

