-- ===================== Judges — EASY tier (11 items) =====================

with w as (select id from public.world where book_slug = 'judges')
insert into public.challenge (world_id, type, prompt, verse_ref, verse_text, translation, difficulty_rank, difficulty_tier, answer_key, is_boss_item, sort_order)
values
  ((select id from w), 'multiple_choice', 'Who did Yahweh raise up to save Israel from those who plundered them?', 'Judges 2:16', 'Yahweh raised up judges, who saved them out of the hand of those who plundered them.', 'WEB', 1, 'easy',
   '{"type": "multiple_choice", "options": ["judges", "kings", "priests", "prophets"], "correct_index": 0}', false, 1),
  ((select id from w), 'recall', 'Fill in the missing word describing Deborah''s role.', 'Judges 4:4-5', 'Now Deborah, a prophetess, the wife of Lappidoth, judged Israel at that time. She lived under Deborah''s palm tree between Ramah and Bethel in the hill country of Ephraim; and the children of Israel came up to her for judgment.', 'WEB', 1, 'easy',
   '{"type": "recall", "template": "Now Deborah, a prophetess, the wife of Lappidoth, ___ Israel at that time.", "answer": "judged"}', false, 2),
  ((select id from w), 'multiple_choice', 'According to Judges 4:16, what happened to Sisera''s army when Yahweh gave Barak the victory?', 'Judges 4:14-16', 'Deborah said to Barak, ''Go; for this is the day in which Yahweh has delivered Sisera into your hand...'' Yahweh confused Sisera, all his chariots, and all his army, with the edge of the sword before Barak... all the army of Sisera fell by the edge of the sword. There was not a man left.', 'WEB', 1, 'easy',
   '{"type": "multiple_choice", "options": ["The whole army fell by the edge of the sword; not a man was left", "They surrendered without a fight", "They fled and were never seen again", "Barak spared them all"], "correct_index": 0}', false, 3),
  ((select id from w), 'multiple_choice', 'What did Yahweh tell Gideon to do?', 'Judges 6:14-16', 'Yahweh looked at him, and said, ''Go in this your might, and save Israel from the hand of Midian. Haven''t I sent you?'' He said to him, ''O Lord, how shall I save Israel? Behold, my family is the poorest in Manasseh, and I am the least in my father''s house.'' Yahweh said to him, ''Surely I will be with you, and you shall strike the Midianites as one man.''', 'WEB', 1, 'easy',
   '{"type": "multiple_choice", "options": ["Go in his might and save Israel from Midian", "Build an altar before doing anything else", "Gather ten thousand men immediately", "Flee to Egypt"], "correct_index": 0}', false, 4),
  ((select id from w), 'recall', 'Fill in the missing word: what did Gideon put on the threshing floor as a sign?', 'Judges 6:37', '...behold, I will put a fleece of wool on the threshing floor. If there is dew on the fleece only, and it is dry on all the ground, then I''ll know that you will save Israel by my hand, as you have spoken.', 'WEB', 1, 'easy',
   '{"type": "recall", "template": "...behold, I will put a fleece of ___ on the threshing floor.", "answer": "wool"}', false, 5),
  ((select id from w), 'multiple_choice', 'Why did Yahweh say Gideon''s army was too large?', 'Judges 7:2', 'The people who are with you are too many for me to give the Midianites into their hand, lest Israel brag against me, saying, ''My own hand has saved me.''', 'WEB', 1, 'easy',
   '{"type": "multiple_choice", "options": ["So that Israel could not boast the victory was by their own hand", "Because there wasn''t enough food for them", "Because the men were afraid", "Because Midian had a much bigger army"], "correct_index": 0}', false, 6),
  ((select id from w), 'multiple_choice', 'According to Judges 7:20, what did Gideon''s three hundred men shout during the attack on the Midianite camp?', 'Judges 7:20-21', '...they shouted, ''The sword of Yahweh and of Gideon!'' They each stood in his place around the camp, and all the army ran; and they shouted, and put them to flight.', 'WEB', 1, 'easy',
   '{"type": "multiple_choice", "options": ["''The sword of Yahweh and of Gideon!''", "''Long live the king!''", "''Peace be with you''", "They shouted nothing"], "correct_index": 0}', false, 7),
  ((select id from w), 'multiple_choice', 'According to Judges 21:25, what was true of Israel in those days?', 'Judges 21:25', 'In those days there was no king in Israel. Everyone did that which was right in his own eyes.', 'WEB', 1, 'easy',
   '{"type": "multiple_choice", "options": ["There was no king in Israel, and everyone did what was right in his own eyes", "The judges had all died out", "The land was completely at peace", "The people had forgotten the law"], "correct_index": 0}', false, 8),
  ((select id from w), 'sequence', 'Put these steps of the judges'' cycle, as the narrator describes it, in the order they happen in the text.', 'Judges 2:11-19', 'Yahweh''s anger burned against Israel, and he delivered them into the hands of raiders who plundered them. He sold them into the hands of their enemies all around, so that they could no longer stand before their enemies.; Yahweh raised up judges, who saved them out of the hand of those who plundered them.; When Yahweh raised up judges for them, then Yahweh was with the judge, and saved them out of the hand of their enemies all the days of the judge... But when the judge was dead, they turned back, and dealt more corruptly than their fathers...', 'WEB', 1, 'easy',
   '{"type": "sequence", "items": ["Israel does evil and is handed over to raiders", "Yahweh raises up a judge who delivers them", "when the judge dies, the people fall back into the same pattern"], "correct_order": [0, 1, 2]}', true, 9),
  ((select id from w), 'multiple_choice', 'According to Judges 7:2, why did Yahweh tell Gideon to reduce his army?', 'Judges 7:2', 'The people who are with you are too many for me to give the Midianites into their hand, lest Israel brag against me, saying, ''My own hand has saved me.''', 'WEB', 1, 'easy',
   '{"type": "multiple_choice", "options": ["So that Israel could not claim credit for the victory itself", "Because there wasn''t enough food for them", "Because the men were afraid", "Because Midian had a much bigger army"], "correct_index": 0}', true, 10),
  ((select id from w), 'recall', 'Fill in the missing word: what did the Israelites do after each judge died?', 'Judges 2:19', 'When Yahweh raised up judges for them, then Yahweh was with the judge, and saved them out of the hand of their enemies all the days of the judge... But when the judge was dead, they turned back, and dealt more corruptly than their fathers...', 'WEB', 1, 'easy',
   '{"type": "recall", "template": "...But when the judge was dead, they turned back, and dealt more ___ than their fathers...", "answer": "corruptly"}', true, 11)
;

