  ((select id from w), 'multiple_choice', 'According to Ruth 1:8-9, what did Naomi urge her two daughters-in-law to do?', 'Ruth 1:8-9', 'Naomi said to her two daughters-in-law, ''Go, return each of you to her mother''s house... May Yahweh grant you that you may find rest, each of you in the house of her husband.''', 'WEB', 1, 'easy',
   '{"type": "multiple_choice", "options": ["Return each of them to her mother''s house", "Come with her to Bethlehem", "Glean in the fields of Bethlehem", "Marry Boaz"], "correct_index": 0}', false, 2),
  ((select id from w), 'multiple_choice', 'In whose field did Ruth happen to glean grain?', 'Ruth 2:2-3', 'Ruth the Moabitess said to Naomi, ''Let me now go to the field, and glean among the ears of grain after him in whose sight I find favor.''... she happened to come to the portion of the field belonging to Boaz, who was of the family of Elimelech.', 'WEB', 1, 'easy',
