  ((select id from w), 'multiple_choice', 'What did Boaz tell Ruth he had heard about her?', 'Ruth 2:11-12', '...I have been told all about what you have done for your mother-in-law since the death of your husband... May Yahweh repay your work, and a full reward be given to you from Yahweh, the God of Israel, under whose wings you have come to take refuge.', 'WEB', 1, 'easy',
   '{"type": "multiple_choice", "options": ["All she had done for her mother-in-law since her husband''s death", "That she was wealthy in Moab", "That she planned to return to Moab", "That she was Naomi''s servant"], "correct_index": 0}', false, 4),
  ((select id from w), 'multiple_choice', 'What did Ruth ask Boaz to do at the threshing floor?', 'Ruth 3:9', '...She answered, ''I am Ruth your servant. Therefore spread the corner of your garment over your servant; for you are a near kinsman.''', 'WEB', 1, 'easy',
   '{"type": "multiple_choice", "options": ["Spread the corner of his garment over her, because he was a near kinsman", "Give her a place to sleep for the night", "Redeem the land on her behalf immediately", "Send her back to Naomi"], "correct_index": 0}', false, 5),
  ((select id from w), 'multiple_choice', 'According to Ruth 4:21-22, who was Boaz''s son?', 'Ruth 4:21-22', '...and Salmon became the father of Boaz, and Boaz became the father of Obed, and Obed became the father of Jesse, and Jesse became the father of David.', 'WEB', 1, 'easy',
