  ((select id from w), 'recall', 'Fill in the missing word: what did Boaz call the elders and people at the gate?', 'Ruth 4:9-10', 'Boaz said to the elders and to all the people, ''You are witnesses today, that I have bought all that was Elimelech''s, and all that was Chilion''s and Mahlon''s, from the hand of Naomi. Moreover, Ruth the Moabitess, the wife of Mahlon, I have purchased to be my wife... You are witnesses today.''', 'WEB', 1, 'easy',
   '{"type": "recall", "template": "Boaz said to the elders and to all the people, ''You are ___ today...''", "answer": "witnesses"}', true, 7),
  ((select id from w), 'multiple_choice', 'According to Ruth 4:17, who was Obed''s grandson?', 'Ruth 4:17', 'The women, her neighbors, gave him a name, saying, ''A son is born to Naomi''. They named him Obed. He is the father of Jesse, the father of David.', 'WEB', 1, 'easy',
   '{"type": "multiple_choice", "options": ["David", "Boaz", "Jesse", "Salmon"], "correct_index": 0}', true, 8),
  ((select id from w), 'recall', 'Fill in the missing word from Naomi''s question to Ruth about Boaz.', 'Ruth 3:1-2', 'Naomi her mother-in-law said to her, ''My daughter, shall I not seek rest for you, that it may be well with you? Now isn''t Boaz our kinsman, with whose maidens you were?''', 'WEB', 1, 'easy',
   '{"type": "recall", "template": "Now isn''t Boaz our ___, with whose maidens you were?", "answer": "kinsman"}', true, 9)
